// Builds supabase/bundle/all-migrations.sql: every migration in order, in one transaction,
// for pasting into the Supabase SQL editor when the CLI cannot reach the project.
// It also records each migration as applied, so a later `supabase db push` agrees.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const dir = new URL('../supabase/migrations/', import.meta.url).pathname
const files = readdirSync(dir).filter((f) => f.endsWith('.sql')).sort()
const parts = [
  '-- GENERATED by scripts/bundle-migrations.mjs. Do not edit; edit supabase/migrations/ and rebuild.',
  '-- Paste the whole file into the Supabase SQL editor of an EMPTY project and run it once.',
  'begin;',
  "do $$ begin if exists (select 1 from pg_tables where schemaname = 'public' and tablename = 'spots') then raise exception 'Pull Up is already installed in this project'; end if; end $$;",
]
for (const f of files) parts.push(`\n-- ═══════════ ${f} ═══════════\n`, readFileSync(join(dir, f), 'utf8'))
parts.push(
  '\n-- ═══════════ record the migrations as applied ═══════════',
  'create schema if not exists supabase_migrations;',
  'create table if not exists supabase_migrations.schema_migrations (version text primary key, statements text[], name text);',
  ...files.map((f) => {
    const [, version, name] = f.match(/^(\d+)_(.+)\.sql$/)
    return `insert into supabase_migrations.schema_migrations (version, name) values ('${version}', '${name}') on conflict do nothing;`
  }),
  'commit;',
  "select 'Pull Up database installed' as result, count(*) as tables from pg_tables where schemaname = 'public';",
)
const out = new URL('../supabase/bundle/all-migrations.sql', import.meta.url).pathname
writeFileSync(out, parts.join('\n') + '\n')
console.log(`wrote ${out} (${files.length} migrations)`)
